
export function getSystemTheme() {
	return window.matchMedia("(prefers-color-scheme: dark)").matches ? "dark" : "light"
}

export const updateHTMLTagColor = (isDark) => {
	const htmlTag = document.querySelector("html")
	htmlTag.classList.add(`${isDark ? "bg-zinc-950" : "bg-gray-50"}`)
	htmlTag.classList.remove(`${!isDark ? "bg-zinc-950" : "bg-gray-50"}`)
}

export const toggleTheme = () => {
	const currentTheme = localStorage.theme || getSystemTheme()
	const newTheme = currentTheme === "dark" ? "light" : "dark"
	setTheme(newTheme)
}

export const setTheme = (theme) => {
	localStorage.theme = theme

	const isDark = theme === "dark"
	updateHTMLTagColor(isDark)
	document.documentElement.classList.toggle("dark", isDark)
}

export function toggleHiddenClass(selector, shouldHide) {
	document.querySelectorAll(selector).forEach(element => {
		element.classList.toggle("hidden", shouldHide)
	})
}

export function safeJSONParse(str, fallback = []) {
	try {
		return JSON.parse(str)
	} catch (e) {
		console.warn("Failed to parse JSON:", str)
		return fallback
	}
}

/**
 * Capitalizes the first letter of a string, preserving special characters
 * @param {string} str - The string to capitalize
 * @returns {string} The string with its first letter capitalized
 */
function capitalizeFirst(str) {
	if (!str) return ""
	return str.charAt(0).toUpperCase() + str.slice(1)
}

/**
 * Converts a string to title case, capitalizing the first letter of each word
 * @param {string} str - The string to convert to title case
 * @returns {string} The string in title case
 * @example
 * toTitleCase("hello, world!") // "Hello, World!"
 * toTitleCase("garcía lópez") // "García López"
 * toTitleCase("de la rosa") // "De la Rosa"
 */
export function toTitleCase(str) {
	if (!str) return ""

	// Handle special cases for articles and prepositions
	const lowercaseWords = ["de", "del", "la", "las", "los", "el", "y", "e"]

	return str
		.toLowerCase()
		.split(/\s+/)
		.map(word => {
			// Handle hyphenated names (e.g., García-López)
			if (word.includes("-")) {
				return word
					.split("-")
					.map(part => capitalizeFirst(part))
					.join("-")
			}

			// Keep articles and prepositions lowercase unless they're the first word
			return lowercaseWords.includes(word) ? word : capitalizeFirst(word)
		})
		.join(" ")
}
