// questions.js

import { API } from "../api.js"
import { SERVER_URL } from "../environment.js"
import { showModalX } from "../modals.js"
import { loadComponent } from "../router.js"
import { apiRequest } from "../utils.js"

const MAX_LOCAL_QUESTIONS = 1500
const QUESTIONS_MAX_DISPLAY = 1500
const QUESTIONS_PAGE_SIZE = 200
const QUESTIONS_FUZZY_SEARCH = false

let totalQuestions = 0
let allQuestions = []
let currentPage = 1
let displayCount = 200 // Initial number of questions to display
let isLoading = false
let currentSortField = null
let sortDirection = "asc"

export async function initializeQuestions() {
	// First check total questions count
	// const total = await checkTotalQuestions()
	// total <= MAX_LOCAL_QUESTIONS ? await loadAllQuestions() : await loadMoreQuestions()
	await loadAllQuestions()

	// Event listeners
	document.querySelector("#loadMoreQuestions")?.addEventListener("click", () => {
		if (!isLoading) loadMoreQuestions()
	})
	document.querySelector("#questionSearch").addEventListener("input", (e) => {
		filterQuestions(e.target.value)
	})
	// document.querySelector("#sortByTema")?.addEventListener("click", () => {
	// 	sortQuestionsByTema()
	// })
	// CSV upload handling
	document.querySelector("#uploadCsv").addEventListener("click", () => {
		document.querySelector("#csvUpload").click()
	})

	document.querySelector("#csvUpload").addEventListener("change", handleCsvUpload)
}

function sortQuestionsByTema() {
	if (currentSortField === "tema") {
		// Toggle direction if already sorting by tema
		sortDirection = sortDirection === "asc" ? "desc" : "asc"
	} else {
		currentSortField = "tema"
		sortDirection = "asc"
	}

	const sortedQuestions = [...allQuestions].sort((a, b) => {
		const extraA = a.extra ? a.extra : {}
		const extraB = b.extra ? b.extra : {}

		const lessonA = extraA.lesson || ""
		const lessonB = extraB.lesson || ""

		// Try to parse as numbers first
		const numA = parseInt(lessonA)
		const numB = parseInt(lessonB)

		if (!isNaN(numA) && !isNaN(numB)) {
			// Both are numbers
			return sortDirection === "asc" ? numA - numB : numB - numA
		}

		// If not numbers, compare as strings
		if (sortDirection === "asc") {
			return lessonA.localeCompare(lessonB, "es", { numeric: true })
		} else {
			return lessonB.localeCompare(lessonA, "es", { numeric: true })
		}
	})

	// Update the arrow icon direction
	// const sortButton = document.querySelector("#sortByTema")
	// if (sortButton) {
	// 	const svg = sortButton.querySelector("svg")
	// 	if (sortDirection === "asc") {
	// 		svg.classList.remove("rotate-180")
	// 	} else {
	// 		svg.classList.add("rotate-180")
	// 	}
	// }

	// Update display
	renderQuestions(sortedQuestions.slice(0, displayCount))
	updateSearchStats(sortedQuestions.length)
}


async function checkTotalQuestions() {
	try {
		const response = await fetch(`${SERVER_URL}questions?limit=1`)
		const data = await response.json()
		return data.total || 0
	} catch (error) {
		console.error("Failed to get total questions:", error)
		return Infinity // Fallback to API mode
	}
}

async function loadAllQuestions() {
	try {
		isLoading = true
		showLoadingState()

		const { questions, total } = await fetchQuestions({ limit: MAX_LOCAL_QUESTIONS })
		allQuestions = questions
		currentPage = 1

		renderQuestions(allQuestions.slice(0, displayCount))
		updateSearchStats(Math.min(QUESTIONS_PAGE_SIZE, allQuestions.length))

		// Hide load more if all questions are displayed
		if (allQuestions.length <= displayCount) {
			document.querySelector("#loadMoreQuestions").style.display = "none"
		}
	} catch (error) {
		console.error("Failed to load questions:", error)
		showModalX("error", "Error", "Error cargando preguntas")
	} finally {
		resetLoadingState()
		isLoading = false
	}
}

function loadMoreQuestions() {
	if (isLoading) return

	displayCount = Math.min(
		displayCount + QUESTIONS_PAGE_SIZE,
		QUESTIONS_MAX_DISPLAY,
		allQuestions.length
	)
	renderQuestions(allQuestions.slice(0, displayCount))
	updateSearchStats(displayCount)

	// Hide button when reaching max display and show finish message
	if (displayCount >= Math.min(allQuestions.length, QUESTIONS_MAX_DISPLAY)) {
		document.querySelector("#loadMoreQuestions").style.display = "none"
		const countElement = document.querySelector("#countDisplay")
		if (countElement) {
			var x = document.createElement("div")
			var t = document.createTextNode("Ya no hay más preguntas para mostrar.")
			x.appendChild(t)
			countElement.appendChild(x)
		}
	}
}

function filterQuestions(searchTerm) {
	if (!searchTerm) {
		// const questionsToShow = currentSortField === "tema" ?
		// 	sortQuestionsByTema() :
		// 	allQuestions.slice(0, displayCount)
		// renderQuestions(questionsToShow)
		renderQuestions(allQuestions.slice(0, displayCount))
		updateSearchStats(allQuestions.length)
		return
	}

	const filtered = allQuestions.filter(question => {
		const searchText = [
			question.question,
			question.explanation,
			...question.answers,
			question.year?.toString(),
			question.categoryNames?.join(" ")
		].join(" ").toLowerCase()

		const term = searchTerm.toLowerCase()
		return QUESTIONS_FUZZY_SEARCH ?
			fuzzyMatch(searchText, term) :
			searchText.includes(term)
	})

	// // Apply current sort if exists
	// if (currentSortField === "tema") {
	// 	filtered.sort((a, b) => {
	// 		const extraA = a.extra ? safeJSONParse(a.extra, {}) : {}
	// 		const extraB = b.extra ? safeJSONParse(b.extra, {}) : {}
	// 		const lessonA = extraA.lesson || ""
	// 		const lessonB = extraB.lesson || ""
	// 		return sortDirection === "asc" ?
	// 			lessonA.localeCompare(lessonB, "es", { numeric: true }) :
	// 			lessonB.localeCompare(lessonA, "es", { numeric: true })
	// 	})
	// }

	renderQuestions(filtered.slice(0, displayCount))
	updateSearchStats(filtered.length)
}

// Simple fuzzy match implementation
function fuzzyMatch(text, search) {
	let searchIndex = 0
	text = text.normalize("NFD").replace(/[\u0300-\u036f]/g, "")
	search = search.normalize("NFD").replace(/[\u0300-\u036f]/g, "")

	for (let i = 0; i < text.length; i++) {
		if (text[i] === search[searchIndex]) {
			if (++searchIndex === search.length) return true
		}
	}
	return false
}

async function handleCsvUpload(event) {
	const file = event.target.files[0]
	if (!file) return

	const formData = new FormData()
	formData.append("file", file)

	try {
		const response = await fetch(SERVER_URL + "questions/upload", {
			method:      "POST",
			body:        formData,
			credentials: "include",
			headers:     {
				"Accept": "application/json"
			}
		})

		const data = await response.json()
		if (!response.ok) {
			throw new Error(data.error?.details || data.message || "Upload failed")
		}

		if (data.success) {
			const stats = data.data.stats
			const processingTime = data.meta?.processingTimeMs

			const message = `
                <div class="space-y-2">
                    <p class="font-medium">CSV procesado correctamente</p>
                    <div class="text-sm space-y-1">
                        <p>✓ ${stats.totalProcessed} filas de CSV procesadas</p>
                        <p>✓ ${stats.questionsProcessed} preguntas procesadas</p>
                        <p>✓ ${stats.questionsAdded} preguntas añadidas</p>
                        <p>✓ ${stats.categoriesAdded} categorías nuevas</p>
                        <p>✓ ${stats.regionsAdded} regiones nuevas</p>
                        <p>✓ ${stats.institutionsAdded} instituciones nuevas</p>
                        ${processingTime ? `<p class="text-xs text-zinc-200 mt-2">Tiempo de procesamiento: ${processingTime}ms</p>` : ""}
						${stats.errors.length ? `<p class="text-xs text-red-500 mt-4">✗ ${stats.errors.join("<br>✗ ")}</p>` : ""}
                    </div>
                </div>
            `

			showModalX("success", "Subida del CSV exitosa", message)
			loadMoreQuestions() // Refresh questions list
		} else {
			const message = `
                <div class="space-y-2">
                    <p class="font-medium">Se han encontrado errores al procesar el CSV</p>
                    <div class="text-sm space-y-1">
                        <p>⚠️ ${data.error.details}</p>
                    </div>
                </div>
            `
			showModalX("error", data.error.code, message)
		}
	} catch (error) {
		console.error("Upload error:", error)

		const errorMessage = `
            <div class="space-y-2">
                <p class="font-medium">Error al procesar el CSV</p>
                <p class="text-sm text-red-500">${error.message}</p>
                ${error.details ? `<p class="text-xs mt-2">${error.details}</p>` : ""}
            </div>
        `

		showModalX("error", "Error de Importación", errorMessage)
	}

	// Reset file input
	event.target.value = ""
}

function updateSearchStats(count) {
	const countElement = document.querySelector("#countDisplay")
	if (countElement) {
		const total = totalQuestions || allQuestions.length
		countElement.textContent = count === total ?
			`Mostrando ${Math.min(count, QUESTIONS_MAX_DISPLAY)} de ${total} preguntas` :
			`Mostrando ${count} resultados de ${total} preguntas`
	}
}

function renderQuestions(questions) {
	const tbody = document.querySelector("#questionsBody")

	if (!questions.length) {
		tbody.innerHTML = `
            <tr>R
                <td colspan="3" class="px-4 py-8 text-center text-zinc-200">
                    No se encontraron preguntas que coincidan con tu búsqueda
                </td>
            </tr>
        `
		return
	}

	tbody.innerHTML = questions.map(question => {
		// const answers = safeJSONParse(question.answers, [])
		// const extra = question.extra ? safeJSONParse(question.extra, {}) : {}

		return `
      <tr class="hover:bg-zinc-950/[2.5%] dark:hover:bg-white/[2.5%] cursor-pointer group"
          data-question-id="${question.id}">
          <td class="px-4 py-3">${question.id || ""}</td>
          <td class="px-4 py-3">
              ${truncate(question.question || "", 60)}
              ${question.year ? `<div class="text-xs text-zinc-500">Año: ${question.year}</div>` : ""}
          </td>
          <td class="px-4 py-3">
            <div class="text-sm">
              ${question.answers
					.map((answer, index) => `${String.fromCharCode(65 + index)}) ${answer}`)
					.join("<br>")}
              ${question.accepted !== undefined ? `
                  <div class="text-xs text-zinc-500">
                      Respuesta correcta: ${question.answers[question.accepted] || ""}
                  </div>
              ` : ""}
            </div>
          </td>
		   <td class="px-4 py-3">
              <div class="text-sm">
                  ${question.extra.lesson || ""}
              </div>
          </td>
          <!--
		  <td class="px-4 py-3 text-right">
              <div class="space-y-1">
                  <button class="text-indigo-500 hover:text-indigo-700 mr-2"
                          hx-get="/api/questions/${question.id}/edit"
                          hx-target="closest tr">Editar</button>
                  <button class="text-red-500 hover:text-red-700"
                          hx-delete="/api/questions/${question.id}"
                          hx-confirm="¿Eliminar esta pregunta?">Eliminar</button>
              </div>
          </td>
		  -->
      </tr>
    `
	}).join("")


	// Add click handlers for entire row
	document.querySelectorAll("[data-question-id]").forEach(row => {
		row.addEventListener("click", (e) => {
			// Don't navigate if clicking buttons
			if (e.target.tagName === "BUTTON" || e.target.closest("button")) return

			const questionId = row.getAttribute("data-question-id")
			loadComponent(`/questions/${questionId}`)
		})
	})
}

function truncate(text, length) {
	return text.length > length ? text.substring(0, length) + "..." : text
}

async function fetchQuestions(params = {}) {
	const api = API.endpoints.QUESTIONS.BASE
	const schema = API.getSchemaForEndpoint("QUESTIONS.BASE")
	const queryString = API.buildQueryString(schema, params)

	try {
		const { response, error } = await apiRequest(api + queryString, "GET", {})
		if (error) throw error

		if (!response?.questions || !Array.isArray(response.questions)) {
			console.error("Invalid API response structure")
			return { questions: [], total: 0 }
		}

		return {
			questions: response.questions,
			total:     response.total || response.questions.length
		}
	} catch (err) {
		console.error("Fetch Questions Failed:", err)
		return { questions: [], total: 0 }
	}
}

function updatePaginationControls(total) {
	const paginationElement = document.querySelector("#pagination")
	if (!paginationElement) return

	const totalPages = Math.ceil(total / QUESTIONS_PAGE_SIZE)

	paginationElement.innerHTML = `
        <div class="flex items-center justify-between px-4 py-3 sm:px-6">
            <div class="flex flex-1 justify-between sm:hidden">
                <button ${currentPage <= 1 ? "disabled" : ""}
                    class="pagination-btn relative inline-flex items-center px-4 py-2 text-sm font-semibold
                    ${currentPage <= 1 ? "text-gray-400 cursor-not-allowed" : "text-gray-700 hover:bg-gray-50"}"
                    onclick="changePage(${currentPage - 1})">
                    Anterior
                </button>
                <button ${currentPage >= totalPages ? "disabled" : ""}
                    class="pagination-btn relative ml-3 inline-flex items-center px-4 py-2 text-sm font-semibold
                    ${currentPage >= totalPages ? "text-gray-400 cursor-not-allowed" : "text-gray-700 hover:bg-gray-50"}"
                    onclick="changePage(${currentPage + 1})">
                    Siguiente
                </button>
            </div>
            <div class="hidden sm:flex sm:flex-1 sm:items-center sm:justify-between">
                <div>
                    <p class="text-sm text-gray-700">
                        Mostrando página <span class="font-medium">${currentPage}</span> de
                        <span class="font-medium">${totalPages}</span>
                    </p>
                </div>
                <div class="flex space-x-2">
                    ${Array.from({ length: totalPages }, (_, i) => i + 1)
						.map(page => `
                            <button
                                class="pagination-btn relative inline-flex items-center px-4 py-2 text-sm
                                ${page === currentPage
									? "bg-indigo-600 text-white"
									: "text-gray-900 ring-1 ring-inset ring-gray-300 hover:bg-gray-50"}"
                                onclick="changePage(${page})">                                ${page}
                            </button>
                        `).join("")}
                </div>
            </div>
        </div>
    `
}

async function changePage(page) {
	if (isLoading || page === currentPage) return
	if (page < 1) return

	isLoading = true
	currentPage = page

	try {
		const { questions, total } = await fetchQuestions({
			offset: (page - 1) * QUESTIONS_PAGE_SIZE,
			limit:  QUESTIONS_PAGE_SIZE
		})
		totalQuestions = page * QUESTIONS_PAGE_SIZE + QUESTIONS_PAGE_SIZE
		renderQuestions(questions)
		updatePaginationControls(total)
		// updateCountDisplay(total)
		updateCountDisplay(0)

		// Scroll to top of questions
		document.querySelector("#questionsBody")?.scrollIntoView({ behavior: "smooth" })
	} catch (error) {
		console.error("Error changing page:", error)
	} finally {
		isLoading = false
	}
}

function updateCountDisplay(total) {
	const countElement = document.querySelector("#countDisplay")
	if (countElement) {
		const start = ((currentPage - 1) * QUESTIONS_PAGE_SIZE) + 1
		const end = Math.min(currentPage * QUESTIONS_PAGE_SIZE, total)
		countElement.textContent = `Mostrando ${start}-${end} de ${total} preguntas`
	}
}

function showLoadingState() {
	const loadMoreBtn = document.querySelector("#loadMoreQuestions")
	if (loadMoreBtn) {
		loadMoreBtn.innerHTML = "<span class=\"loading\">Cargando...</span>"
		loadMoreBtn.disabled = true
	}
}

function resetLoadingState() {
	const loadMoreBtn = document.querySelector("#loadMoreQuestions")
	if (loadMoreBtn) {
		loadMoreBtn.innerHTML = "Cargar más"
		loadMoreBtn.disabled = false
	}
}

// Add to window for onclick handlers
window.changePage = changePage
