	calculateSuccessRatio(userStats) {
		if (!Array.isArray(userStats) || userStats.length === 0) {
			return 0
		}

		// Calculate totals directly from all stats
		const totals = userStats.reduce((acc, stat) => {
			acc.passed += stat.questions_passed
			acc.failed += stat.questions_failed
			acc.listed += stat.questions_listed
			return acc
		}, { passed: 0, failed: 0, listed: 0 })

		// Calculate success ratio
		const totalAnswered = totals.passed + totals.failed
		if (totalAnswered === 0) {
			return 0
		}

		return parseFloat((totals.passed / totalAnswered * 100).toFixed(2))
	}

	calculateStreak(userStats) {
		if (!Array.isArray(userStats) || userStats.length === 0) {
			return 0
		}
		const today = new Date()

		// Sort stats by date in descending order (most recent first)
		const sortedStats = userStats.sort((a, b) =>
			new Date(b.stat_date) - new Date(a.stat_date)
		)

		// remove today's stats if empty
		const todayStats = sortedStats[0]
		const todayDate = new Date(todayStats.stat_date)
		if (todayStats && todayStats.questions_passed + todayStats.questions_failed + todayStats.questions_listed === 0) {
			const isToday = today.toDateString() === todayDate.toDateString()
			if (isToday) sortedStats.shift()
		}

		// Check if most recent activity was today or yesterday
		today.setHours(0, 0, 0, 0)
		const mostRecentDate = new Date(sortedStats[0].stat_date)
		const daysSinceLastActivity = Math.floor((today - mostRecentDate) / (1000 * 60 * 60 * 24))

		if (daysSinceLastActivity > 1) {
			return 0 // Break streak if no activity in last two days
		}

		// Count consecutive days
		let streak = 0
		let previousDate = null

		for (const stat of sortedStats) {
			const currentDate = new Date(stat.stat_date)
			const hasActivity = stat.questions_passed + stat.questions_failed + stat.questions_listed > 0

			if (!hasActivity) {
				break
			}

			if (previousDate) {
				const dayDifference = Math.floor((previousDate - currentDate) / (1000 * 60 * 60 * 24))
				if (dayDifference !== 1) {
					break // Break streak if days aren't consecutive
				}
			}

			streak++
			previousDate = currentDate
		}

		return streak
	}

	calculateSubmissionScore(submission) {
		const part = submission.submissionMode // FIXME: Replace by a real database value, such as submission.submissionMode
		const config = GAME_PARTS_CONFIG[getGamePartKeyFromType(part)]

		const relevantQuestions = submission.questionsAnswers.slice(0, config.validQuestions)
		const correct = relevantQuestions.filter(a => a.selectedAnswer === a.accepted).length
		const incorrect = relevantQuestions.filter(a => a.selectedAnswer !== a.accepted && a.selectedAnswer !== null).length

		// Calculate final score with more precision
		const finalScore = Number((correct * config.pointsPerCorrect - incorrect * config.pointsPerIncorrect).toFixed(3))
		// No rounding needed here since we already have precise calculation
		const normalizeScore = Math.max(0, Math.min(10, finalScore)).toFixed(3)

		return normalizeScore
	}

