	/**
	 * Normalizes statistics response data for chart visualization
	 * @param {Array<Object>} statsResponse - Array of statistics objects from the API
	 * @param {string} statsResponse[].month - Month in YYYY-MM format
	 * @param {number} statsResponse[].lesson_id - Unique identifier for the lesson
	 * @param {string} statsResponse[].lesson_name - Name of the lesson
	 * @param {number} statsResponse[].lesson_type - Type of lesson (0: general, 1: específica)
	 * @param {number} statsResponse[].lesson_number - Lesson number
	 * @param {number} statsResponse[].passed - Number of passed questions
	 * @param {number} statsResponse[].failed - Number of failed questions
	 * @param {number} statsResponse[].blank - Number of blank questions
	 * @returns {Object} Normalized data for chart rendering
	 * @property {Object} chartData - Object containing lesson data arrays
	 * @property {number[]} chartData[key] - Array of monthly values for each lesson
	 * @property {string} chartData[key].name - Formatted lesson name with type
	 * @property {number} chartData[key].type - Lesson type (0: general, 1: específica)
	 * @property {number} chartData[key].number - Lesson number
	 * @property {string[]} chartLegend - Array of formatted lesson names for chart legend
	 *
	 * @example
	 * // Example statsResponse
	 * const stats = [
	 *   { month: "2025-02", lesson_id: 1, lesson_name: "Volcanes", lesson_type: 0, lesson_number: 1, passed: 5 },
	 *   { month: "2025-02", lesson_id: 2, lesson_name: "Mareas", lesson_type: 1, lesson_number: 1, passed: 3 }
	 * ];
	 *
	 * // Example return value
	 * {
	 *   chartData: {
	 *     "1": [5, 0, 0, 0, 0, 0], name: "Volcanes (general)", type: 0, number: 1,
	 *     "2": [3, 0, 0, 0, 0, 0], name: "Mareas (específica)", type: 1, number: 1
	 *   },
	 *   chartLegend: ["Volcanes (general)", "Mareas (específica)"]
	 * }
	 */
	normalizeStatsResponseV0(statsResponse) {
		const monthsFromResponse = [...new Set(statsResponse.map(s => s.month))].sort()

		// Group data by lesson_id and month
		// e.g: [{ "month": "2025-02", "lesson_id": 1, "lesson_number": 0, "lesson_name": "Undefined", "lesson_type": 0, "passed": 0, "failed": 0, "blank": 0 }]
		const normalizedStats = statsResponse.reduce((acc, { lesson_id, lesson_name, lesson_type, lesson_number, month, passed }) => {
			if (!acc[lesson_id]) {
				// Initialize array with zeros for all months
				acc[lesson_id] = new Array(monthsFromResponse.length).fill(0)
				acc[lesson_id].name = lesson_name
				acc[lesson_id].type = lesson_type
				acc[lesson_id].number = lesson_number
			}

			// Find index for current month and update value
			const monthIndex = monthsFromResponse.indexOf(month)
			if (monthIndex !== -1) {
				acc[lesson_id][monthIndex] += passed
			}

			return acc
		}, {})

		return {
			chartData:   normalizedStats,
			chartLegend: Object.values(normalizedStats).map(lesson => lesson.name)
		}
	}

	normalizeStatsResponse(statsResponse) {
		const monthsFromResponse = [...new Set(statsResponse.map(s => s.month))].sort()

		// Group data by lesson_number and type
		const normalizedStats = statsResponse.reduce((acc, { lesson_id, lesson_name, lesson_type, lesson_number, month, passed }) => {
			// Skip lesson_number 0 (Undefined)
			if (lesson_number === 0) return acc

			// Create unique key for lesson
			const key = lesson_id

			if (!acc[key]) {
				acc[key] = {
					name:   key,
					type:   lesson_type,
					number: lesson_number,
					data:   new Array(monthsFromResponse.length).fill(0),
					alias:  `${lesson_name} (${this.lessonTypes[lesson_type]})`
				}
			}

			// Find index for current month and update value
			const monthIndex = monthsFromResponse.indexOf(month)
			if (monthIndex !== -1) {
				acc[key].data[monthIndex] += passed
			}

			return acc
		}, {})

		// Convert to an array of objects to ensure sorting
		const sortedStatsArray = Object.entries(normalizedStats)
			.map(([key, value]) => ({ key, ...value }))
			.sort((a, b) => {
				// Sort by type first (0 before 1)
				if (a.type !== b.type) {
					return a.type - b.type
				}
				// Then sort by lesson number
				return a.number - b.number
			})

		return sortedStatsArray
		// return {
		// 	chartData:   sortedStatsArray,
		// 	chartLegend: sortedStatsArray.map(lesson => lesson.alias)
		// }
	}

