	calculateLowestPassingScore(submission) {
		if (submission.submissionType === "simulation") {
			return SUCCESS_THRESHOLD_SIMULATION * 10
		}
		return SUCCESS_THRESHOLD_STUDY * 10
	}

	prepareDashBoardTable(submissions) {
		try {
			// Convert the response data to a table format
			return submissions.map((submission) => {
				const total = submission.questionsAnswers.length
				// const correctAnswers = submission.questionsAnswers.filter((answer) => answer.selectedAnswer === answer.accepted).length
				const correctAnswers = submission.answersPassed
				const numericalScore = submission.submissionType === "simulation"
					? this.calculateSubmissionScore(submission)
					: correctAnswers
				const isApproved = numericalScore >= this.calculateLowestPassingScore(submission)
				const status = submission.submissionType === "simulation"
					? numericalScore : isApproved ? translations[userLanguage]["badgePass"] : translations[userLanguage]["badgeFail"]
				const statusTooltip = submission.submissionType === "simulation"
					? this.getSimulationTooltip(submission.submissionMode, correctAnswers, total)
					: this.getStudyTooltip(numericalScore, total)

				// Check if the submission is a simulation or study and get the corresponding text
				let textType = submission.submissionType === "simulation"
					? "Simulacro"
					: "Estudio"

				if (submission.submissionMode) {
					textType += ` (${translations[userLanguage][submission.submissionMode]})`
				}

				// Format the date
				const date = new Date(submission.createdAt).toLocaleString("es-ES", {
					year:   "numeric",
					month:  "short",
					day:    "numeric",
					hour:   "2-digit",
					minute: "2-digit",
					hour12: false // Use 24-hour format
				})

				// Return the formatted table row object
				return {
					id:            submission.id,
					date:          date,
					type:          textType,
					score:         `${correctAnswers}/${total}`,
					isApproved:    isApproved,
					status:        status,
					statusTooltip: statusTooltip,
					link:          `/results/${submission.id}`
				}
			})
		} catch (err) {
			console.error("Unexpected error in prepareDashBoardTable:", err)
			return []
		}

	}

	createDashboardTable(submissions) {
		// Render the table
		const tableContainer = document.querySelector("#submissions-table")
		if (!tableContainer) return
		if (submissions.length === 0) {
			tableContainer.innerHTML = "<p class='mt-3 text-sm/6 sm:text-xs/6 text-zinc-500'>Aún no hay resultados recientes</p>"
			return
		}
		if (tableContainer.childElementCount > 0) {
			// console.warn("Updating an already existing table")
			tableContainer.innerHTML = "" // Clear existing content
		}
		const tableElement = generateSubmissionsTable(submissions)
		tableContainer.appendChild(tableElement)
	}

