	/**
	 * Calculates success rate for a specific number of days
	 * @param {Array} stats - Array of daily statistics
	 * @param {number} daysBack - Number of days to calculate
	 * @returns {number} Success rate percentage or 0 if no data
	 */
	calculateSuccessRateForDays(stats, daysBack) {
		if (!Array.isArray(stats) || stats.length === 0) {
			return 0
		}

		// Sort by date descending and get last n days
		const relevantStats = stats
			.sort((a, b) => new Date(b.stat_date) - new Date(a.stat_date))
			.slice(0, daysBack)

		// Calculate totals for the period
		const totals = relevantStats.reduce((acc, stat) => {
			acc.passed += stat.questions_passed
			acc.failed += stat.questions_failed
			return acc
		}, { passed: 0, failed: 0 })

		const totalAnswered = totals.passed + totals.failed
		if (totalAnswered === 0) {
			return 0
		}

		return parseFloat((totals.passed / totalAnswered * 100).toFixed(2))
	}

	/**
	 * Determines the best interval for calculating improvement
	 * @param {Array} stats - Array of daily statistics
	 * @returns {Object} Best interval info
	 */
	determineBestInterval(stats) {
		if (!Array.isArray(stats) || stats.length === 0) {
			return { days: 0, hasData: false }
		}

		// Sort stats by date descending
		const sortedStats = stats.sort((a, b) =>
			new Date(b.stat_date) - new Date(a.stat_date)
		)

		// Define intervals to check
		const intervals = [7, 10, 15, 20, 30]

		// Find first interval with data
		for (const days of intervals) {
			const relevantStats = sortedStats.slice(0, days)
			const hasActivity = relevantStats.some(stat =>
				stat.questions_passed + stat.questions_failed > 0
			)

			const todayRate = this.calculateSuccessRateForDays(relevantStats, 1)
			const periodRate = this.calculateSuccessRateForDays(relevantStats, days)

			return {
				days,
				hasData:    hasActivity,
				todayRate:  todayRate,
				periodRate: periodRate
			}

		}

		return { days: 0, hasData: false }
	}

	/**
	 * Calculates the number of passed submissions
	 * @param {Array} submissions - Array of submission history
	 * @returns {Object} Count of passed simulations and studies
	 */
	calculatePassedSubmissions(submissions) {
		return submissions.reduce((acc, submission) => {
			if (!submission.questionsAnswers?.length) {
				return acc
			}

			if (submission.submissionType === "simulation") {
				const score = this.calculateSubmissionScore(submission)
				const isApproved = score >= this.calculateLowestPassingScore(submission)
				if (isApproved) acc.simulations++

			} else if (submission.submissionType === "study") {
				const successRate = submission.answersPassed / submission.questionsAnswers.length
				const isApproved = successRate >= SUCCESS_THRESHOLD_STUDY
				if (isApproved) acc.studies++
			}

			return acc
		}, { simulations: 0, studies: 0 }) // Initialize with zero counts
	}

	determineImprovement(interval) {
		if (!interval.hasData) return null
		if (interval.periodRate === 0) return interval.todayRate > 0 ? 100 : 0 // Would be interesting to show a negative improvement to just show that the period rate is being calculated.
		if (interval.todayRate === 0) return interval.periodRate // Return 0 when today's rate is 0

		// Calculate improvement percentage
		const improvementPercent = ((interval.todayRate - interval.periodRate) / Math.abs(interval.periodRate) * 100)
		// Cap at 1000% and return numeric value
		return Math.min(improvementPercent, 1000)
	}

	formatImprovement(value) {
		if (value === null) return "--"
		return `${value > 0 ? "+" : ""}${value.toFixed(1)}%`
	}

	getStreakDescription (streak) {
		if (streak === 0) return "¡Empieza hoy tu racha de estudio!"
		if (streak < 5) return "Cada día cuenta para fortalecer tu conocimiento."
		if (streak < 10) return "¡Increíble constancia! Mantén el ritmo."
		if (streak < 15) return "¡Excelente dedicación! Tu esfuerzo se nota."
		if (streak < 20) return "¡Impresionante compromiso! Eres una inspiración."
		return "¡Legendario! Tu dedicación es extraordinaria."
	}

	prepareDashboardCards(userDailyStats, streak, successRatio, submissionsHistory) {
		const interval = this.determineBestInterval(userDailyStats)
		const improvement = this.determineImprovement(interval)

		const passed = this.calculatePassedSubmissions(submissionsHistory)
		const passedCount = passed.simulations || passed.studies
		const passedType = passed.simulations > 0 ? "simulacro" : "estudio"

		const dashboardCards = [
			{
				title:       "Racha de días",
				value:       streak,
				description: this.getStreakDescription(streak),
				changeColor: "bg-blue-400/20 text-blue-700 dark:bg-blue-400/10 dark:text-blue-300",
				flame:       true,
			},
			{
				title:       `Progreso diario, últimos ${interval.days} días`,
				value:       this.formatImprovement(improvement),
				description: interval.hasData
					? improvement > 0
						? "¡Excelente progreso! Sigue así, vas por buen camino."
						: "No te preocupes por los altibajos, ¡cada error es una oportunidad de aprendizaje!"
					: "Sin datos suficientes. ¿A qué esperas para empezar?",
				changeColor: improvement > 0
					? "bg-lime-400/20 text-lime-700 dark:bg-lime-400/10 dark:text-lime-300"
					: "bg-red-400/20 text-red-700 dark:bg-red-400/10 dark:text-red-300",
				iconSrc: booksSvg
			},
			{
				title:       "Tasa de éxito",
				value:       successRatio ? successRatio : "-- " + "%",
				description: successRatio ? "Porcentaje de preguntas correctas sobre las respondidas." : "Sin datos suficientes para calcular.",
				changeColor: "bg-blue-400/20 text-blue-700 dark:bg-blue-400/10 dark:text-blue-300",
				iconSrc:     trophyStarSvg
			},
			{
				title:       `${toTitleCase(passedType)}${passedCount === 1 ? "" : "s"} aprobado${passedCount === 1 ? "" : "s"}`,
				value:       `${passedCount}`,
				description: "Cada prueba superada es un paso más hacia el aprobado.",
				changeColor: "bg-blue-400/20 text-blue-700 dark:bg-blue-400/10 dark:text-blue-300",
				iconSrc:     verifiedSvg
			}
		]

		return dashboardCards
	}

